import{_ as t,c as a,o as r,a9 as i,av as o}from"./chunks/framework.Bqk8xQPS.js";const b=JSON.parse('{"title":"NATS Event Bridge","description":"Use NATS with PURISTA","frontmatter":{"title":"NATS Event Bridge","description":"Use NATS with PURISTA","order":301050},"headers":[],"relativePath":"handbook/3_eco_system/eventbridges/nats.md","filePath":"handbook/3_eco_system/eventbridges/nats.md","lastUpdated":1775116212000}'),n={name:"handbook/3_eco_system/eventbridges/nats.md"};function s(l,e,d,c,p,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<p><img src="'+o+'" alt="NATS event bridge"></p><h1 id="nats-event-bridge" tabindex="-1">NATS Event Bridge <a class="header-anchor" href="#nats-event-bridge" aria-label="Permalink to “NATS Event Bridge”">​</a></h1><p>The <code>@purista/natsbridge</code> package integrates NATS subject-based routing.</p><h2 id="delivery-semantics" tabindex="-1">Delivery semantics <a class="header-anchor" href="#delivery-semantics" aria-label="Permalink to “Delivery semantics”">​</a></h2><p>For core NATS without JetStream persistence, behavior is typically:</p><ul><li>durability: no persistent backlog</li><li>retries: application-level retry patterns required</li><li>typical delivery mode: at-most-once</li></ul><p>When JetStream is available, subscriptions and durable commands can use JetStream consumers with explicit acknowledgements.</p><p>For subscriptions, PURISTA now supports a bounded consumer failure policy:</p><ul><li>manual ack path for <code>autoacknowledge: false</code></li><li>configurable retry budget (<code>consumerFailureHandling.maxAttempts</code>)</li><li>configurable retry delay (<code>consumerFailureHandling.retryDelayMs</code>)</li><li>dead-letter publish to an explicit subject or a derived default subject</li><li>strict startup validation when <code>consumerFailureHandling.mode</code> is left at the safe default (<code>strict</code>)</li></ul><p>The default NATS bridge configuration applies a bounded retry budget for JetStream-backed subscriptions. Per-subscription failure handling hints override that adapter default. JetStream processing timeout/redelivery is configured at broker level via <code>jetStreamAckWaitMs</code> (or command-specific timeout override), so redelivery is driven by JetStream rather than a PURISTA timer loop.</p><p>If a registration requests <code>durable: true</code> against a broker without JetStream, the bridge fails fast in <code>strict</code> mode instead of silently falling back to non-durable core NATS behavior.</p><h2 id="stream-support" tabindex="-1">Stream support <a class="header-anchor" href="#stream-support" aria-label="Permalink to “Stream support”">​</a></h2><p>PURISTA stream runtime (<code>openStream</code>) is currently not implemented for NATS bridge.</p><h2 id="reliability-recommendations" tabindex="-1">Reliability recommendations <a class="header-anchor" href="#reliability-recommendations" aria-label="Permalink to “Reliability recommendations”">​</a></h2><ul><li>design handlers idempotent even when retries are app-driven</li><li>keep subject prefix configuration identical across instances</li><li>enable JetStream on the broker when you rely on <code>durable: true</code></li><li>keep dead-letter subjects on JetStream as operator inboxes and replay them intentionally</li><li>monitor dead-letter subjects and treat them as operator inboxes, not silent sinks</li><li>prefer queue bridges for long-running workflows or replay-heavy remediation</li><li>validate timeout/error behavior under broker disconnect scenarios</li></ul>',15)])])}const h=t(n,[["render",s]]);export{b as __pageData,h as default};
